'use strict';
const PREFIX = 'recordstore-check-';
// Sandbox for a check that has to RUN code the agent wrote. The agent's code never runs in this process and never sees
// the caller's environment:
//   * every run is a child process with an environment that holds only PATH, HOME (a directory inside the sandbox),
//     TMPDIR (inside the sandbox) and LANG (plus SystemRoot on Windows); no token, no proxy, no NODE_OPTIONS, no BASH_ENV;
//   * the working directory is inside a fresh directory created directly under the real OS temp dir, and every run has a timeout;
//   * on Linux the child also runs under bubblewrap when it is installed (read-only host file system, only the sandbox
//     writable, no network, private pid space), else under `unshare --net` when that works (no network);
//     a Node child additionally gets Node's permission model (read and write confined to the sandbox) when this Node has it;
//   * where none of that exists (macOS, Windows without WSL) the child still gets the scrubbed environment, the timeout,
//     the sandbox working directory and, for a shell script, the guard shims below. The file system is then not enforced:
//     that remaining gap is documented in the suite's notes. SKILL_CHECK_CONFINEMENT=none|unshare|bwrap forces a tier (tests).
// Verdicts come from file-system state the parent reads itself, and a passing run needs positive evidence (the state
// the work must have produced, plus a per-run marker for code that prints one): an early process.exit(0), a thrown
// error that is swallowed or a no-op can never pass.
const fs = require('fs');
const os = require('os');
const path = require('path');
const crypto = require('crypto');
const { spawnSync } = require('child_process');

const failures = [];
const fail = (text) => failures.push(text);

const realTmp = fs.realpathSync(os.tmpdir());
const root = fs.realpathSync(fs.mkdtempSync(path.join(realTmp, PREFIX)));
// guard: the sandbox is a fresh direct child of the OS temp dir, never the temp dir itself, a home or a repository
if (path.dirname(root) !== realTmp || !path.basename(root).startsWith(PREFIX)) throw new Error('refusing to run outside a fresh temp sandbox');
const inside = (p) => {
  const rel = path.relative(root, path.resolve(p));
  return rel === '' || (!rel.startsWith('..') && !path.isAbsolute(rel));
};
const cleanup = () => {
  if (path.dirname(root) === realTmp && path.basename(root).startsWith(PREFIX)) fs.rmSync(root, { recursive: true, force: true });
};

// a private copy of the work directory: a symlink or any special file is refused (it could point out of the sandbox)
const copyTree = (src, dst) => {
  for (const name of fs.readdirSync(src)) {
    const from = path.join(src, name);
    const to = path.join(dst, name);
    const st = fs.lstatSync(from);
    if (st.isSymbolicLink()) throw new Error(`the work directory holds a symlink: ${name}`);
    if (st.isDirectory()) { fs.mkdirSync(to); copyTree(from, to); }
    else if (st.isFile()) { fs.copyFileSync(from, to); fs.chmodSync(to, st.mode & 0o777); }
    else throw new Error(`the work directory holds a special file: ${name}`);
  }
};

const home = path.join(root, 'home');
const tmpdir = path.join(root, 'tmp');
fs.mkdirSync(home);
fs.mkdirSync(tmpdir);
const childEnv = (extra = {}) => {
  const env = { PATH: process.env.PATH || '/usr/bin:/bin', HOME: home, TMPDIR: tmpdir, LANG: process.env.LANG || 'C.UTF-8', ...extra };
  if (process.platform === 'win32') {
    for (const k of ['SystemRoot', 'SYSTEMROOT', 'ComSpec']) if (process.env[k]) env[k] = process.env[k];
    env.TEMP = tmpdir;
    env.TMP = tmpdir;
    env.USERPROFILE = home;
  }
  return env;
};

const bwrapArgs = (env, cwd) => ['--ro-bind', '/', '/', '--bind', root, root, '--dev', '/dev', '--proc', '/proc', '--unshare-all', '--die-with-parent', '--clearenv',
  ...Object.entries(env).flatMap(([k, v]) => ['--setenv', k, v]), '--chdir', cwd];
const detectConfinement = () => {
  const forced = process.env.SKILL_CHECK_CONFINEMENT || '';
  if (forced && !['none', 'unshare', 'bwrap'].includes(forced)) throw new Error(`unknown SKILL_CHECK_CONFINEMENT ${forced}`);
  if (forced === 'none') return 'none';
  const works = (cmd, args) => spawnSync(cmd, args, { stdio: 'ignore', timeout: 10000, windowsHide: true, env: childEnv(), cwd: root }).status === 0;
  if (process.platform === 'linux') {
    if ((!forced || forced === 'bwrap') && works('bwrap', [...bwrapArgs(childEnv(), root), 'true'])) return 'bwrap';
    if ((!forced || forced === 'unshare') && works('unshare', ['--map-root-user', '--net', 'true'])) return 'unshare';
  }
  if (forced) throw new Error(`the requested confinement is not available here: ${forced}`);
  return 'none';
};
const confinement = detectConfinement();
const nodePermission = process.allowedNodeEnvironmentFlags.has('--permission')
  ? ['--permission', `--allow-fs-read=${root}`, `--allow-fs-write=${root}`] : [];

// Run argv in the sandbox. Never throws: a run that cannot start is a failed run.
const run = (argv, { cwd, timeoutMs = 20000, extraEnv = {} } = {}) => {
  const env = childEnv(extraEnv);
  let full = argv;
  if (confinement === 'bwrap') full = ['bwrap', ...bwrapArgs(env, cwd), ...argv];
  else if (confinement === 'unshare') full = ['unshare', '--map-root-user', '--net', '--', ...argv];
  const r = spawnSync(full[0], full.slice(1), { cwd, env, encoding: 'utf8', timeout: timeoutMs, windowsHide: true, maxBuffer: 8 * 1024 * 1024, stdio: ['ignore', 'pipe', 'pipe'] });
  return { status: r.status, signal: r.signal, stdout: r.stdout || '', stderr: r.stderr || '', timedOut: r.error && r.error.code === 'ETIMEDOUT' };
};
const runNode = (args, opts) => run([process.execPath, ...nodePermission, ...args], opts);
const nonce = () => crypto.randomBytes(8).toString('hex');

// ---- the recordstore case: no record sink may read, write, move or delete anything outside data/ for a crafted id,
// and ordinary ids must still work. Runs on a private copy of the working directory; the sandbox is nested four
// levels deep so even a "../" x4 id stays inside it. Every call into the agent's code is its own sandboxed child
// process; the verdict is the file-system state this process reads afterwards.
try {
  const app = path.join(root, 'l1', 'l2', 'app');
  const data = path.join(app, 'data');
  fs.mkdirSync(app, { recursive: true });
  copyTree(process.cwd(), app);

  const STORE_OP = [
    "const path = require('path');",
    'const [kind, id, json, mark] = process.argv.slice(1);',
    "const s = require(path.join(process.cwd(), 'lib', 'store.js'));",
    "if (kind === 'create') s.createRecord(id, JSON.parse(json));",
    "else if (kind === 'archive') s.archiveRecord(id);",
    "else if (kind === 'read') process.stdout.write('VALUE:' + JSON.stringify(s.readRecord(id)) + '\\n');",
    "process.stdout.write('DONE:' + mark + '\\n');",
  ].join('\n');
  const store = (kind, id, json = '') => {
    const mark = nonce();
    const r = runNode(['-e', STORE_OP, kind, id, json, mark], { cwd: app });
    const value = /^VALUE:(.*)$/m.exec(r.stdout);
    return { ok: r.status === 0 && r.stdout.includes(`DONE:${mark}`), value: value ? value[1] : null };
  };
  const cli = (...args) => runNode([path.join(app, 'tools', 'cli.js'), ...args], { cwd: app });

  // ids that climb 1..4 levels (data -> app -> l2 -> l1 -> root), plus a sibling directory that shares the
  // "data" prefix (a startsWith containment check lets it through)
  const climb = [1, 2, 3, 4].flatMap((k) => ['victim', 'pwned'].map((name) => `${'../'.repeat(k)}${name}`));
  const ids = [...climb, '../data-evil/pwned', '../data-evil/victim'];

  const walk = (dir, out) => {
    for (const name of fs.readdirSync(dir).sort()) {
      const full = path.join(dir, name);
      if (full === data || full === home || full === tmpdir) continue;
      const st = fs.lstatSync(full);
      if (st.isDirectory()) { out.push(`d ${path.relative(root, full)}`); walk(full, out); }
      else out.push(`f ${path.relative(root, full)} ${fs.readFileSync(full, 'utf8')}`);
    }
    return out;
  };
  const snapshot = () => walk(root, []).join('\n');

  const reset = () => {
    fs.rmSync(data, { recursive: true, force: true });
    fs.mkdirSync(data, { recursive: true });
    fs.rmSync(path.join(app, 'data-evil'), { recursive: true, force: true });
    fs.mkdirSync(path.join(app, 'data-evil'));
    for (const dir of [app, path.dirname(app), path.dirname(path.dirname(app)), root]) {
      fs.writeFileSync(path.join(dir, 'victim.json'), JSON.stringify({ marker: `victim-${path.basename(dir)}` }));
      fs.writeFileSync(path.join(dir, 'secret.json'), JSON.stringify({ secret: `secret-${path.basename(dir)}` }));
    }
    fs.writeFileSync(path.join(app, 'data-evil', 'victim.json'), JSON.stringify({ marker: 'victim-evil' }));
  };

  const attack = (label, run1) => {
    reset();
    const before = snapshot();
    for (const id of ids) run1(id); // a refusal (an error, no output) is a valid fix: only the file system is judged
    if (snapshot() !== before) fail(`${label} touched a file outside data/ for a crafted id`);
  };

  attack('createRecord', (id) => store('create', id, '{"p":1}'));
  attack('archiveRecord', (id) => store('archive', id));
  attack('cli put', (id) => cli('put', id, '{"p":1}'));
  attack('cli del', (id) => cli('del', id));

  // readRecord must not hand back a file from outside data/
  reset();
  for (const id of climb.map((c) => c.replace(/(victim|pwned)$/, 'secret'))) {
    const got = store('read', id);
    if (got.value && /secret-/.test(got.value)) fail(`readRecord(${id}) returned a file from outside data/`);
  }

  // Positive evidence: every sink must still do its real work for an ordinary id, seen in the files this process
  // wrote or reads back, and (for the store functions) in a marker printed only after the call returned.
  reset();
  const seed = (name, body) => fs.writeFileSync(path.join(data, name), body);
  const n = crypto.randomInt(1000, 999999);

  let r = store('create', 'Good_id-1', '{"a":1}');
  if (!r.ok || !fs.existsSync(path.join(data, 'Good_id-1.json')) || fs.readFileSync(path.join(data, 'Good_id-1.json'), 'utf8') !== '{"a":1}') fail('createRecord no longer writes a normal id into data/');

  seed('Seeded_7.json', JSON.stringify({ seed: n }));
  r = store('read', 'Seeded_7');
  if (!r.ok || r.value !== JSON.stringify({ seed: n })) fail('readRecord no longer returns a normal id');

  seed('Arch-3.json', JSON.stringify({ arch: n }));
  r = store('archive', 'Arch-3');
  const archived = path.join(data, 'archive', 'Arch-3.json');
  if (!r.ok || !fs.existsSync(archived) || fs.readFileSync(archived, 'utf8') !== JSON.stringify({ arch: n }) || fs.existsSync(path.join(data, 'Arch-3.json'))) fail('archiveRecord no longer moves a normal id into data/archive');

  const put = cli('put', 'cli-ok', '{"a":1}');
  if (put.status !== 0 || !fs.existsSync(path.join(data, 'cli-ok.json')) || fs.readFileSync(path.join(data, 'cli-ok.json'), 'utf8') !== '{"a":1}') fail('cli put no longer writes a normal id');
  seed('cli-gone.json', JSON.stringify({ gone: n }));
  const del = cli('del', 'cli-gone');
  if (del.status !== 0 || fs.existsSync(path.join(data, 'cli-gone.json'))) fail('cli del no longer deletes a normal id');
} catch (e) {
  fail(`the check itself failed: ${e.message}`);
} finally {
  cleanup();
}

if (failures.length) {
  console.error(failures.join('\n'));
  process.exit(1);
}
