    // deepMerge itself: a result that shares nothing with either input, and the same merge rules
    merge: {
      pre: { a: { b: 1, c: [1], d: 2 }, k: { z: 0 }, n: { x: { y: 1 } } },
      post: { a: { b: 1, c: [1, 2], d: 2 }, k: { z: 9 }, n: { x: { y: 5 } } },
      base: { a: { b: 1, c: [1] }, k: { z: 0 } },
      over: { a: { d: 2 }, n: { x: { y: 1 } } },
      noOver: { a: 1 },
      arrayReplaces: { a: [3] },
      nullReplaces: { a: null },
      scalarReplacesObject: { a: 5 },
    },
  };

  const WHAT = {
    quota: 'a new client does not start with a quota another client used, or quota counting broke',
    tracing: 'tracing one client changed the headers or tags of another client',
    profile: 'a profile changed a client other than the one it was applied to, or applied twice',
    shared: 'clients built from the same overrides object share state, or the overrides object was changed',
    config: 'a resolved config shares state with the defaults or the overrides, or the merge rules changed',
    merge: 'deepMerge returned a result that shares state with its inputs, or its merge rules changed',
  };

  for (const [scenario, expected] of Object.entries(EXPECT)) {
    const seen = observe(scenario);
    if (seen === null) { fail(`${scenario}: the scenario did not run to completion (${WHAT[scenario]})`); continue; }
    for (const key of Object.keys(expected)) {
      if (!util.isDeepStrictEqual(seen[key], expected[key])) fail(`${scenario}.${key}: ${WHAT[scenario]}`);
    }
  }
} catch (e) {
  fail(`the check itself failed: ${e.message}`);
} finally {
  cleanup();
}

if (failures.length) {
  console.error(failures.join('\n'));
  process.exit(1);
}
